create table claim (
	created_at timestamp(6) with time zone not null,
	updated_at timestamp(6) with time zone not null,
	id uuid not null,
	participation_id uuid,
	content text not null,
	primary key (id)
);

create table claim_skill (
	claim_id uuid not null,
	skill_id uuid not null,
	primary key (claim_id, skill_id)
);

create table education (
	completed_at date,
	expected boolean,
	started_at date,
	workload_hours integer,
	created_at timestamp(6) with time zone not null,
	updated_at timestamp(6) with time zone not null,
	id uuid not null,
	degree varchar(100),
	institution varchar(100) not null,
	title varchar(120) not null,
	description text,
	type EducationType not null,
	primary key (id)
);

create table event_publication (
	completion_attempts integer not null,
	completion_date timestamp(6) with time zone,
	last_resubmission_date timestamp(6) with time zone,
	publication_date timestamp(6) with time zone not null,
	id uuid not null,
	event_type varchar(255) not null,
	listener_id varchar(255) not null,
	serialized_event varchar(255) not null,
	status varchar(255) check ((status in ('PUBLISHED','PROCESSING','COMPLETED','FAILED','RESUBMITTED'))),
	primary key (id)
);

create table experience (
	ended_at date,
	started_at date,
	created_at timestamp(6) with time zone not null,
	updated_at timestamp(6) with time zone not null,
	client_id uuid,
	employer_id uuid not null,
	id uuid not null,
	employment_type varchar(40) not null,
	role varchar(200) not null,
	description text,
	primary key (id)
);

create table job (
	created_at timestamp(6) with time zone not null,
	updated_at timestamp(6) with time zone not null,
	id uuid not null,
	company_name varchar(100) not null,
	title varchar(160) not null,
	description text not null,
	primary key (id)
);

create table job_compensation (
	job_id uuid not null,
	salary varchar(120),
	benefits text[] not null,
	salary_period SalaryPeriod default 'MONTHLY',
	primary key (job_id)
);

create table job_location (
	job_id uuid not null,
	country varchar(56),
	state varchar(60),
	city varchar(80),
	work_mode WorkMode,
	primary key (job_id)
);

create table job_posting (
	created_at timestamp(6) with time zone not null,
	published_at timestamp(6) with time zone,
	updated_at timestamp(6) with time zone not null,
	id uuid not null,
	job_id uuid not null,
	provider varchar(40) not null,
