	claim_id uuid,
	education_id uuid,
	id uuid not null,
	participation_id uuid,
	model varchar(100) not null,
	hash varchar(128) not null,
	primary key (id),
	constraint ck_knowledge_chunk_one_source check (num_nonnulls(participation_id, claim_id, education_id) = 1)
);

create table language (
